python3 -c "
import os, shutil, time, glob
t = os.environ.get('TMPDIR', '/tmp'); now = time.time(); n = 0
for p in glob.glob(os.path.join(t, 'elephc_*')):
    try:
        if now - os.path.getmtime(p) > 7200:
            shutil.rmtree(p, ignore_errors=True); n += 1
    except OSError: pass
print('purged', n)
